const D=window.WARDOGS, main=document.querySelector('main');
let offerPeriod=1;const offerServers={};const money=value=>Number(value).toFixed(2).replace(/\.00$/,'');const periodText=months=>months===1?'month':months+' months';
const discord=(label='Join Discord',cls='button primary')=>`<a class="${cls}" href="${D.discord}" target="_blank" rel="noopener noreferrer">${label} <span>↗</span></a>`;
const badge=s=>`<span class="badge ${s}"><i class="dot"></i>${s}</span>`;
const heading=(eyebrow,title,desc='')=>`<section class="pagehead"><p class="eyebrow">${eyebrow}</p><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</section>`;
const rules=`<ol class="rules"><li><strong>Respect the people behind the players.</strong> No harassment, hate speech, threats or targeted abuse.</li><li><strong>Keep the game fair.</strong> No cheats, exploits or deliberate disruption. Report suspected cheating privately to staff.</li><li><strong>Play for the squad.</strong> Follow the game mode and staff instructions. Server-specific settings will be published before launch.</li><li><strong>Keep personal information private.</strong> Don’t post someone else’s details or private messages.</li><li><strong>Give staff the details.</strong> For reports, include the server, approximate time and evidence where available. Appeals go through Discord.</li></ol><p class="note">Draft community rules · Final rules and moderation process will be confirmed before launch.</p>`;
function serverCard(s){return `<article class="servercard"><div class="server-top"><span class="server-id">ZA / ${s.id==='za-01'?'01':'02'}</span>${badge(s.status)}</div><div class="server-graphic" aria-hidden="true"><span>${s.slots}</span><small>PLAYER SLOTS</small><div class="crosshair">+</div></div><div class="server-body"><p class="eyebrow">${s.game} <span> / </span> ${s.region}</p><h3>${s.name}</h3><div class="servermeta"><span>Players <b>${s.players===null?'—':s.players} / ${s.slots}</b></span><span>Supporter reserved <b>${s.reservedSlots}</b></span></div><p class="small muted">${s.status==='planned'?'Coming soon · Player count and reservation availability not connected':'Player count not connected'}</p><a class="textlink" href="#server/${s.id}">View server <span>↗</span></a></div></article>`;}
function news(){return D.announcements.map(a=>`<article class="news"><div class="newsmeta"><span>${a.tag}</span><time>${a.date}</time></div><h3>${a.title}</h3><p>${a.body}</p></article>`).join('');}
const map=`<svg class="terrain" viewBox="0 0 800 700" aria-hidden="true"><defs><pattern id="grid" width="50" height="50" patternUnits="userSpaceOnUse"><path d="M50 0H0V50" fill="none" stroke="#899277" stroke-opacity=".12"/></pattern></defs><rect width="800" height="700" fill="url(#grid)"/><g fill="none" stroke="#80916c" stroke-width="1.5" opacity=".3"><path d="M30 700C-50 420 250 480 170 280S340-20 560 20 650 250 800 270"/><path d="M70 700C-10 440 300 470 210 280S350 20 550 60 640 300 800 310"/><path d="M110 700C50 470 340 460 250 290S380 60 540 100 650 330 800 350"/><path d="M150 700C110 490 380 470 290 300S400 100 530 140 660 370 800 390"/><path d="M190 700C170 510 410 480 330 320S430 140 520 180 670 410 800 430"/><path d="M230 700C230 520 450 500 370 340S450 180 510 220 680 450 800 470"/><path d="M270 700C290 540 480 520 410 360S480 220 510 260 700 500 800 510"/><path d="M310 700C350 560 520 550 450 390S500 280 520 310 720 530 800 550"/></g><path d="M280 520 440 350 590 420 660 240" stroke="#dca94e" opacity=".45" fill="none" stroke-dasharray="5 7"/><g fill="#dca94e"><circle cx="440" cy="350" r="5"/><circle cx="590" cy="420" r="5"/></g><g fill="none" stroke="#dca94e" opacity=".45"><circle cx="440" cy="350" r="20"/><circle cx="590" cy="420" r="20"/></g></svg>`;
function home(){return `<section class="hero"><div class="hero-copy"><p class="eyebrow"><span class="tinyline"></span> WARDOGS ZUID AFRIKA</p><h1>FIND YOUR<br>SQUAD.<br><span>HOLD YOUR<br>GROUND.</span></h1><p>A new home for Wardogs in South Africa. Two servers, a shared Discord, and a community you can help build from day one.</p><div class="actions">${discord()}<a href="#servers" class="button secondary">Explore servers <span>↓</span></a></div><div class="launch-note"><i class="dot"></i><span>COMING SOON <small>Targeting 26 Oct–1 Nov · Date to be confirmed</small></span></div></div><div class="hero-art">${map}<div class="map-label">OPERATIONS / SOUTH AFRICA<br><span>WARDOGS COMMUNITY NETWORK</span></div><div class="map-emblem"><img src="mark.svg" alt="Editable Wardogs community emblem"><span>ZA</span></div><div class="map-node node1"><span>01</span> 100 PLAYERS <small>50 SUPPORTER RESERVED</small></div><div class="map-node node2"><span>02</span> 100 PLAYERS <small>90 SUPPORTER RESERVED</small></div><div class="art-caption"><span>LOCAL GROUND.<br>SHARED PURPOSE.</span><small>TACTICAL MAP / BRAND CONCEPT</small></div></div></section><section class="numbers"><div><strong>02</strong><span>UPCOMING SERVERS</span></div><div><strong>200</strong><span>TOTAL PLAYER CAPACITY</span></div><div><strong>ZA</strong><span>SOUTH AFRICAN HOSTING</span></div><div><strong>140</strong><span>SUPPORTER RESERVED SLOTS</span></div></section><section class="section"><div class="sectiontitle"><div><p class="eyebrow">CHOOSE YOUR GROUND</p><h2>Your next deployment.</h2></div><a href="#servers" class="textlink">All servers ↗</a></div><div class="servergrid">${D.servers.map(serverCard).join('')}</div></section><section class="rally"><p class="eyebrow">MORE THAN A SERVER LIST</p><h2>Good games start<br>with good people.</h2><div class="benefits"><div><span>01 / CONNECT</span><h3>Find your people.</h3><p>Meet fellow players, form a squad and find a familiar name on your next match.</p></div><div><span>02 / BUILD</span><h3>Be here from the start.</h3><p>Share feedback while we get set up. Help shape the community you want to play in.</p></div><div><span>03 / BELONG</span><h3>One place to regroup.</h3><p>Discord is our meeting point for launch updates, questions and everything between games.</p></div></div></section><section class="section"><div class="sectiontitle"><div><p class="eyebrow">FROM THE COMMUNITY</p><h2>Latest dispatches.</h2></div><a href="#announcements" class="textlink">All updates ↗</a></div><div class="newsgrid">${news()}</div></section><section class="section membership-teaser"><div class="sectiontitle"><div><p class="eyebrow">ONE COMMUNITY. YOUR CHOICE.</p><h2>Support the community.<br>Choose your benefit.</h2></div><a href="#memberships" class="textlink">Compare memberships ↗</a></div><div class="teasergrid">${D.plans.map(p=>`<a href="#memberships"><span>DONATION SUBSCRIPTION / ${p.servers===2?'BOTH SERVERS':'ONE SERVER'}</span><h3>${p.name}</h3><strong>$${money(p.prices[1])} <small>USD / month</small></strong><p>${p.benefit==='whitelist'?'Queue priority when the server is full.':'Server capacity held back for eligible members.'}</p><small>Also available every 3 or 6 months · sandbox only ↗</small></a>`).join('')}</div></section><section class="joinstrip"><div><p class="eyebrow">THE FIRST CHAPTER STARTS WITH YOU</p><h2>Squad up before launch.</h2><p>Join Discord. Say hello. Be ready when the servers open.</p></div>${discord()}</section>`;}
function servers(){return heading('SERVER DIRECTORY','Find your ground.','Two 100-player Wardogs servers in South Africa. Server 01 has 50 supporter-reserved slots; Server 02 has 90. Connection details will be published when ready.')+`<section class="section tight"><div class="filters"><label>Status <select id="status-filter"><option value="all">All statuses</option><option value="planned">Planned</option><option value="testing">Testing</option><option value="live">Live</option><option value="offline">Offline</option></select></label><p id="result-count">2 servers · 200 player capacity · 140 supporter reserved</p></div><div class="servergrid" id="server-results">${D.servers.map(serverCard).join('')}</div><div class="legend">${['planned','testing','live','offline'].map(badge).join('')}<span>Status is manually set until monitoring is connected.</span></div></section>`;}
function server(id){let s=D.servers.find(s=>s.id===id);if(!s)return heading('NOT FOUND','Server not found.')+`<a class="button" href="#servers">Back to servers</a>`;return heading('WARDOGS / SOUTH AFRICA',s.name,s.description)+`<section class="section tight"><a class="textlink back" href="#servers">← Server directory</a><div class="detailgrid"><div><div class="panel"><div class="sectiontitle"><h2>Server briefing</h2>${badge(s.status)}</div><dl class="facts"><div><dt>Game</dt><dd>${s.game}</dd></div><div><dt>Region</dt><dd>${s.region}</dd></div><div><dt>Capacity</dt><dd>${s.slots} players</dd></div><div><dt>Current players</dt><dd>Unavailable · integration pending</dd></div><div><dt>Game mode / map</dt><dd>${s.mode}</dd></div><div><dt>Supporter-reserved slots</dt><dd>${s.reservedSlots} of ${s.slots}</dd></div><div><dt>Reservation availability</dt><dd>Not connected yet</dd></div></dl></div><div class="panel"><h2>How to connect</h2><ol class="rules"><li>Join our Discord for the confirmed launch announcement.</li><li>Once live, open Wardogs and look for the confirmed server name in the community server browser.</li><li>Use the join details published here at launch. Exact instructions depend on the final server configuration.</li></ol><p class="notice">Connection address / join code: not yet supplied.</p>${discord('Get launch updates')}</div><div class="panel"><h2>Community rules</h2>${rules}</div></div><aside><div class="panel amberpanel"><p class="eyebrow">PRE-LAUNCH</p><h2>See you on<br>the ground.</h2><p>${D.launch}</p><p>Join details and settings are being prepared.</p></div><div class="panel"><p class="eyebrow">SUPPORT YOUR SERVER</p><h3>${s.reservedSlots} supporter-reserved slots</h3><p>Choose Whitelist queue priority or Reserved capacity on one or both servers through a community donation subscription. Benefits and access syncing are not connected yet.</p><a class="textlink" href="#memberships">Compare memberships ↗</a></div><div class="panel"><h3>Server stats</h3><p>Player counts, match history and performance stats are not connected yet.</p><a class="textlink" href="#stats">Explore the stats demo ↗</a></div></aside></div></section>`;}
function paidTier(p){const months=offerPeriod,amount=p.prices[months],selected=offerServers[p.id]||'za-01';return `<article class="panel tier supporter"><div class="ribbon">COMMUNITY DONATION SUBSCRIPTION</div><p class="eyebrow">${p.benefit==='whitelist'?'QUEUE PRIORITY':'HELD-BACK CAPACITY'} / ${p.servers===2?'BOTH SERVERS':'ONE SERVER'}</p><h2>${p.name}</h2><div class="price">$${money(amount)}<span>USD charged every ${periodText(months)}</span></div><p>${p.benefit==='whitelist'?'Queue priority to bypass waiting lines when the server is full. No server capacity is held back by this offer.':'An allocated portion of server capacity is held back for eligible members so they can join or remain on the server.'}</p><ul class="checks"><li>${p.servers===2?'Benefit covers Server 01 and Server 02':'Benefit covers one chosen server'}</li><li>${p.benefit==='whitelist'?'Whitelist queue priority':'Reserved server capacity'}<small>Planned · game-server integration not connected</small></li><li>Supporter Discord role<small>Planned · account linking and role sync required</small></li><li>Opt-in community recognition</li></ul>${p.servers===1?`<label class="server-choice" for="membership-server-${p.id}">Choose your server<select id="membership-server-${p.id}" data-offer-server="${p.id}"><option value="za-01" ${selected==='za-01'?'selected':''}>Server 01</option><option value="za-02" ${selected==='za-02'?'selected':''}>Server 02</option></select></label>`:'<p class="coverage">SERVER 01 + SERVER 02 <small>100-player capacity on each</small></p>'}<button class="button primary" data-notice="payments" data-plan="${p.id}-${months}m" data-offer="${p.id}" data-months="${months}">Test donation subscription ↗</button><p class="small">Renews every ${periodText(months)} until cancelled. Sandbox only.</p></article>`;}
function memberships(){return heading('COMMUNITY SUPPORT','Keep Wardogs growing.','Support Wardogs Zuid Afrika with a donation subscription and choose the server benefit that suits you.')+`<section class="section tight"><article class="community-tier"><div><p class="eyebrow">COMMUNITY / FREE</p><h2>Everyone has a place here.</h2><p>Join Discord, follow updates and find your squad. Supporting the community is optional.</p></div>${discord('Join for free','button secondary')}</article><div class="panel benefit-definitions"><div><p class="eyebrow">WHITELIST</p><h3>Move up the queue.</h3><p>Queue priority to bypass waiting lines when a server is full. Whitelist access does not hold back capacity.</p></div><div><p class="eyebrow">RESERVED</p><h3>Capacity held for members.</h3><p>Part of the server capacity is allocated to eligible members so they can join or stay on the server.</p></div><p class="note">Whitelist and reserved-slot integrations are not connected yet. Sandbox donation subscriptions do not grant game access.</p></div><div class="sectiontitle"><div><p class="eyebrow">CHOOSE YOUR SUPPORT</p><h2>Four ways to give back.</h2></div><div class="offer-periods" role="group" aria-label="Billing period">${[1,3,6].map(months=>`<button type="button" data-offer-period="${months}" aria-pressed="${offerPeriod===months}" class="${offerPeriod===months?'active':''}">${months===1?'Monthly':'Every '+months+' months'}</button>`).join('')}</div></div><div class="membershipgrid" id="offer-cards">${D.plans.map(paidTier).join('')}</div><div class="tablewrap"><table class="offer-table"><caption>Donation subscriptions · full amount charged in USD each billing period</caption><thead><tr><th>Offer</th><th>Monthly</th><th>Every 3 months</th><th>Every 6 months</th></tr></thead><tbody>${D.plans.map(p=>`<tr><th scope="row">${p.name}</th>${[1,3,6].map(months=>`<td>$${money(p.prices[months])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="note">Your chosen amount is charged in full at the start of each billing period and renews every 1, 3 or 6 months until cancelled. These are community-support donation subscriptions with the stated benefits; the billing commitment remains a recurring subscription. Prices are in USD. Bank conversion charges may apply. All checkout is currently PayPal sandbox testing, with no real charges or game benefits activated.</p><div class="reservation-summary"><div><span>SERVER 01</span><strong>100 <small>players</small></strong><p>50 supporter-reserved slots</p></div><div><span>SERVER 02</span><strong>100 <small>players</small></strong><p>90 supporter-reserved slots</p></div><p>Reserved slots are part of the 100-player capacity. Queue priority does not increase that capacity. Allocation, benefit availability and game-server syncing still need to be connected.</p></div><div class="faq"><p class="eyebrow">GOOD TO KNOW</p><h2>A few quick answers.</h2><details><summary>What does my support go towards?</summary><p>Donation subscriptions support the Wardogs Zuid Afrika community and its servers, with Whitelist or Reserved benefits for the selected servers. Supporting us is optional.</p></details><details><summary>How are Whitelist and Reserved different?</summary><p>Whitelist gives queue priority when the server is full. Reserved holds back part of server capacity for eligible members so they can join or stay. One is a queue benefit; the other is a capacity allocation. Neither is connected in this sandbox preview.</p></details><details><summary>Is the three-month or six-month price paid upfront?</summary><p>Yes. The full displayed amount is charged every three or six months, rather than being split into monthly payments. For example, Whitelist on one server costs $5.50 USD every three months.</p></details><details><summary>Can I cancel?</summary><p>Cancellation stops future automatic renewals. Review the confirmed billing dates in your member area and PayPal. Final benefit expiry and refund terms will be published before live subscriptions open.</p></details><details><summary>Can I support both servers?</summary><p>Choose a both-servers offer for coverage on Server 01 and Server 02. A one-server offer lets you select your server before checkout.</p></details><details><summary>Can I subscribe now?</summary><p>PayPal checkout is sandbox-only. Credentials and sign-in must be configured before testing. Real payments and benefit activation remain disabled.</p></details></div></section>`;}
function stats(){return heading('PLAYER INTELLIGENCE','Every squad has a story.','A preview of future player profiles and leaderboards. All names, scores and activity below are fictional demo data.')+`<section class="section tight"><div class="notice"><strong>DEMO DATA</strong> · Not connected to Wardogs servers. These are not real player rankings.</div><div class="filters"><label>Rank by <select id="rank-filter"><option value="score">Score</option><option value="kills">Kills</option><option value="matches">Matches played</option></select></label><span>Wardogs · All demo players</span></div><div class="tablewrap"><table><thead><tr><th>Rank</th><th>Player</th><th>Score</th><th>Kills</th><th>Matches</th><th>Profile</th></tr></thead><tbody id="rankings">${rankRows('score')}</tbody></table></div><div class="panel"><h2>What will make this live?</h2><p>Server identity, a supported read-only stats service or server event feed, persistent storage and player identity mapping. Server access and Wardogs’ available data must be verified before promising specific metrics.</p><p>When a feed becomes unavailable, show its last update and an unavailable state. Never substitute demo rankings for live records.</p></div></section>`;}
function rankRows(key){return [...D.demoPlayers].sort((a,b)=>b[key]-a[key]).map((p,i)=>`<tr><td class="rank">0${i+1}</td><td><strong>${p.name}</strong></td><td>${p.score.toLocaleString()}</td><td>${p.kills}</td><td>${p.matches}</td><td><a class="textlink" href="#player/${D.demoPlayers.indexOf(p)}">View ↗</a></td></tr>`).join('');}
function player(id){let p=D.demoPlayers[Number(id)];if(!p)return heading('NOT FOUND','Player not found.');return heading('FICTIONAL PLAYER PROFILE',p.name,'Demo profile · No real account or game activity is represented.')+`<section class="section tight"><a class="textlink back" href="#stats">← Demo leaderboard</a><div class="numbers"><div><strong>${p.score.toLocaleString()}</strong><span>DEMO SCORE</span></div><div><strong>${p.kills}</strong><span>DEMO KILLS</span></div><div><strong>${(p.kills/p.deaths).toFixed(2)}</strong><span>DEMO K/D</span></div><div><strong>${p.matches}</strong><span>DEMO MATCHES</span></div></div><div class="panel"><h2>Recent activity · Demo</h2><p>Illustrative match completed · Server 01 · +450 demo score</p><p>Illustrative squad session · Server 02 · +320 demo score</p></div></section>`;}
function community(){return heading('WELCOME TO WARDOGS ZUID AFRIKA','Your squad starts here.','A South African community for Wardogs players. Join us while we build the first two servers.')+`<section class="section tight"><div class="detailgrid"><div><div class="panel"><h2>Three steps to join.</h2><ol class="rules"><li><strong>Join Discord.</strong> Introduce yourself and check the community rules.</li><li><strong>Follow the launch updates.</strong> We’re targeting 26 October–1 November 2026; the exact date is still to be confirmed.</li><li><strong>Find your server.</strong> Connection details will appear in the directory once ready.</li></ol>${discord()}</div><div class="panel"><h2>Play hard. Treat people well.</h2>${rules}</div></div><aside><div class="panel amberpanel"><p class="eyebrow">NEED A HAND?</p><h2>Talk to us.</h2><p>Join Discord and ask staff where to post support requests. For a player report, include the server, time and evidence. Avoid posting private information publicly.</p>${discord('Open Discord','button secondary')}</div><div class="panel"><h3>Independent community</h3><p>Wardogs Zuid Afrika is our community brand. This site does not claim to be the official Wardogs game website.</p></div></aside></div></section>`;}
function account(){return heading('MEMBER AREA','Your place in the squad.','Sign in with Discord to link your community identity. Subscriptions are not open yet.')+'<section class="section tight" id="account-content" aria-live="polite"><p>Checking your account…</p></section>';}
const safe=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function loadAccount(){const target=document.querySelector('#account-content');if(!target)return;try{if(!window.WardogsBilling)throw Error('Unavailable');await window.WardogsBilling.account(target,safe);}catch{if(target.isConnected)target.innerHTML='<div class="panel"><h2>Member service unavailable.</h2><p>Run the local site launcher to use accounts. This page does not represent a paid subscription.</p></div>';}}
function staff(){return heading('STAFF ACCESS','Staff tools are not connected.','Content is maintained in the site’s editable source for this first release.')+`<section class="section tight"><div class="panel"><p class="eyebrow">PROTECTED ADMINISTRATION / PLANNED</p><h2>Build the permissions first.</h2><p>A future staff area will manage server status, listings, announcements, tiers and featured content. It needs server-verified sign-in and role-based permissions before any editor is exposed.</p><dl class="facts"><div><dt>Owner</dt><dd>Staff roles, billing configuration and all content</dd></div><div><dt>Editor</dt><dd>Server listings, announcements and featured content</dd></div><div><dt>Moderator</dt><dd>Community support tools only</dd></div></dl><p>No staff login, editor or public write endpoint exists in this preview. A hidden page or browser setting will never grant staff permissions.</p></div></section>`;}
function render(){const route=location.hash.slice(1)||'home', [page,id]=route.split('/');const pages={home,servers,stats,memberships,community,account,staff,announcements:()=>heading('COMMUNITY DISPATCHES','From the ground up.','Launch news and community updates.')+`<section class="section tight"><div class="newsgrid">${news()}</div></section>`};main.innerHTML=page==='server'?server(id):page==='player'?player(id):pages[page]?pages[page]():heading('404','This page is off the map.')+`<a class="button" href="#home">Return home</a>`;document.title=`${page==='home'?'Find your squad':page.charAt(0).toUpperCase()+page.slice(1)} — Wardogs Zuid Afrika`;document.querySelectorAll('nav a').forEach(a=>{const active=a.hash==='#'+page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.querySelector('header').classList.remove('expanded');document.querySelector('.menu').setAttribute('aria-expanded','false');window.scrollTo(0,0);if(page==='account')loadAccount();if(location.hash)main.focus({preventScroll:true});
document.querySelector('#status-filter')?.addEventListener('change',e=>{let list=D.servers.filter(s=>e.target.value==='all'||s.status===e.target.value);document.querySelector('#server-results').innerHTML=list.length?list.map(serverCard).join(''):`<div class="empty"><h2>No ${e.target.value} servers yet.</h2><p>We’re still getting ready. Check planned servers or follow Discord for updates.</p>${discord()}</div>`;document.querySelector('#result-count').textContent=`${list.length} server${list.length===1?'':'s'} · ${list.reduce((n,s)=>n+s.slots,0)} player capacity · ${list.reduce((n,s)=>n+s.reservedSlots,0)} supporter reserved`;});document.querySelector('#rank-filter')?.addEventListener('change',e=>document.querySelector('#rankings').innerHTML=rankRows(e.target.value));}
document.querySelector('.menu').addEventListener('click',e=>{let expanded=document.querySelector('header').classList.toggle('expanded');e.currentTarget.setAttribute('aria-expanded',String(expanded));});window.addEventListener('hashchange',render);document.addEventListener('DOMContentLoaded',render,{once:true});

document.addEventListener('click',e=>{const button=e.target.closest('[data-offer-period]');if(!button)return;offerPeriod=Number(button.dataset.offerPeriod);document.querySelectorAll('[data-offer-period]').forEach(b=>{const active=Number(b.dataset.offerPeriod)===offerPeriod;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});document.querySelector('#offer-cards').innerHTML=D.plans.map(paidTier).join('');});
document.addEventListener('change',e=>{if(e.target.matches('[data-offer-server]'))offerServers[e.target.dataset.offerServer]=e.target.value;});
